INSERT INTO categories (id, name, description) VALUES 
(1, 'İlk Yardım', 'Suni solunum, kalp masajı, kanamalar ve acil kurtarma teknikleri.'),
(2, 'Trafik ve Çevre', 'Hız sınırları, yol işaretleri, geçiş üstünlüğü kuralları ve çevre bilgisi.'),
(3, 'Motor ve Araç Tekniği', 'Motor çalışma prensibi, yağlama, soğutma sistemleri ve gösterge panelleri.'),
(4, 'Trafik Adabı', 'Trafikte nezaket, sabır, hoşgörü, yardımlaşma ve empati yeteneği.');
