INSERT INTO questions (id, exam_id, category_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES
(1, 1, 1, 'Yetişkin bir kazazedede solunum durması veya kalp durması durumunda uygulanacak olan temel yaşam desteğinde kalp masajı ve yapay solunum oranları hangisinde doğru olarak verilmiştir?', '10 kalp masajı - 1 yapay solunum', '20 kalp masajı - 2 yapay solunum', '30 kalp masajı - 2 yapay solunum', '30 kalp masajı - 5 yapay solunum', 'C', 'Temel Yaşam Desteği (TYD) protokolünde, yetişkinlerde dış kalp masajı ve yapay solunum oranı 30 masaj, 2 yapay solunum (30:2) olarak uygulanır.'),
(2, 1, 2, 'Aksine bir işaret bulunmadıkça, yerleşim yeri dışındaki şehirler arası çift yönlü karayollarında otomobiller için azami hız sınırı saatte kaç kilometredir?', '80', '90', '110', '120', 'B', 'Karayolları Trafik Yönetmeliğine göre otomobiller için azami hız sınırları: Yerleşim yeri içinde 50 km/s, şehirler arası çift yönlü karayollarında 90 km/s, bölünmüş yollarda 110 km/s ve otoyollarda 120 km/s''dir.'),
(3, 1, 2, 'Aşağıdilerden hangisi trafik kazasında asli kusur sayılan hallerdendir?', 'Geçme yasağı olan yerlerde araç geçmek', 'Hız sınırlarına uymak', 'Güvenli takip mesafesini korumak', 'Kavşaklarda geçiş önceliğine uymak', 'A', 'Geçme yasağı olan yerlerde öndeki aracı geçmeye çalışmak ve kaza yapmak, karayolları trafik kanununa göre asli kusur (esas hata) kabul edilir.'),
(4, 1, 3, 'Seyir halindeyken aracın gösterge panelinde yağ lambasının yanması durumunda aşağıdakilerden hangisi yapılmalıdır?', 'Hız artırılarak yola devam edilir.', 'Far anahtarı açılıp kapatılır.', 'Araç güvenli bir yerde durdurulur ve motor stop edilir.', 'Radyatör kapağı açılarak su seviyesi kontrol edilir.', 'C', 'Yağ lambası yandığında motorda yağ kalmamış veya yağ pompası arızalanmış olabilir. Motorun yatak sarmasını engellemek için araç derhal güvenli bir şekilde durdurulup motor stop edilmelidir.'),
(5, 1, 4, 'Trafikte kırmızı ışıkta beklerken yeşil ışık yanar yanmaz arkadaki aracın hemen korna çalması, önündeki aracın hareket etmesini sabırsızca zorlaması durumu trafik adabında hangi kavramla açıklanır?', 'Bencillik', 'Sabırsızlık ve tahammülsüzlük', 'Empati', 'Yardımlaşma', 'B', 'Işık değiştiği anda korna çalmak sabırsızlık, tahammülsüzlük ve nezaket dışı bir davranıştır; bu da trafik adabına aykırı bir durumdur.'),
(6, 2, 1, 'Solunum yolu yabancı bir cisimle tamamen tıkanmış olan bir kazazedeye aşağıdaki manevralardan hangisi uygulanır?', 'Rentek Manevrası', 'Hemlik Manevrası', 'Refleks Manevrası', 'Heimlich Manevrası', 'D', 'Tam tıkanmalarda (konuşamayan, nefes alamayan, ellerini boynuna götüren hastalar) ''Heimlich Manevrası'' (karına bası uygulama) gerçekleştirilir.'),
(7, 2, 2, 'Kanamanın fışkırarak, açık kırmızı renkte ve kalp atımlarıyla uyumlu olması hangi kanama türüne aittir?', 'Toplardamar kanaması', 'Kılcal damar kanaması', 'Atardamar kanaması', 'İç kanama', 'C', 'Atardamarlar temiz ve oksijence zengin kan taşır. Bu yüzden kan rengi açık kırmızıdır ve kalbin basısıyla fışkırarak akar.'),
(8, 2, 2, 'Aşağıdakilerden hangisi geçiş üstünlüğüne sahip araçların geçiş önceliği sıralamasında ilk sırada yer alır?', 'İtfaiye araçları', 'Ambulans ve organ nakil araçları', 'Polis ve koruma araçları', 'Kar küreme ve yol yapım araçları', 'B', 'Geçiş üstünlüğünün sıralaması CİP-S formülüdür: Can kurtaran (Ambulans) > İtfaiye > Polis > Sivil Savunma.'),
(9, 2, 3, 'Benzinli bir motorda silindir içerisindeki yakıt-hava karışımı aşağıdakilerden hangisi ile ateşlenir?', 'Buji ile kıvılcım çıkararak', 'Enjektör ile motorin püskürterek', 'Kızdırma bujisi ile ısıtarak', 'Karbüratör yardımıyla bası uygulayarak', 'A', 'Benzinli ve LPG''li araçlarda ateşleme elemanı bujidir. Dizel motorlarda ise enjektör ile yakıt püskürtülerek ateşleme sağlanır.'),
(10, 2, 4, 'Karlı bir günde yoldaki su birikintisini fark etmesine rağmen hızını düşürmeden geçip kaldırımdaki yayaları ıslatan sürücü, hangi değere sahip olmadığını gösterir?', 'Nezaket ve Saygı', 'Bencillik', 'Empati yeteneği yüksek olma', 'Sorumluluk bilinci taşıma', 'A', 'Başkalarına zarar verebilecek durumlarda özen göstermemek nezaket ve saygı eksikliğini gösterir.'),
(11, 3, 1, 'Şok pozisyonunda kazazedenin bacakları yaklaşık kaç santimetre yukarı kaldırılır?', '15', '30', '45', '60', 'B', 'Beyne kan gitmesini kolaylaştırmak amacıyla şok pozisyonunda kazazedenin ayakları 30 cm yukarı kaldırılır.'),
(12, 3, 2, 'Trafik işaret levhalarına zarar veren kişiye ne uygulanır?', 'Zarar karşılığı masraflar ödetilir ve yasal işlem yapılır', 'Sadece uyarı verilir', 'Hiçbir ceza verilmez', 'Trafikten ömür boyu men edilir', 'A', 'Kamu malı olan trafik işaretlerine zarar verenlere verilen zararın masrafı ödetilir ve haklarında mala zarar vermekten yasal işlem yapılır.'),
(13, 3, 2, 'Kaza yerinde araçtan yaralı çıkarılırken boyun ve omuriliğe zarar vermemek için hangi manevra uygulanır?', 'Heimlich manevrası', 'Rentek manevrası', 'İtfaiyeci yöntemi', 'Sürükleme yöntemi', 'B', 'Omurilik hasarlarını ve felci önlemek amacıyla yaralı araçtan ''Rentek Manevrası'' kullanılarak çıkarılır.'),
(14, 3, 3, 'Motor yağı kontrol edilirken yağ seviyesi yağ çubuğunun neresinde olmalıdır?', 'Alt çizgisinin altında', 'Üst çizgisinin üzerinde', 'İki çizgi arasında', 'Yağ çubuğunun en ucunda', 'C', 'Yağ seviyesi ideal yağlama için yağ çubuğundaki iki çizginin (min ve max) tam arasında olmalıdır.'),
(15, 3, 4, 'Kırmızı ışıkla birlikte yanan sarı ışıkta ne yapılır?', 'Yolun trafiğe açılacağını gösterir, kalkışa hazırlanılır.', 'Yolun kapanacağını gösterir, durulur.', 'Trafik kuralları gereği hızlanılır.', 'Geri vitese takılıp beklenir.', 'A', 'Kırmızıdan sonra yanan sarı ışık yolun trafiğe açılacağını bildirir ve kalkışa hazırlanmayı gerektirir.'),
(16, 4, 1, 'Yaralanmalarda, yaralıyı sedye ile taşırken baş ve boyun bölgesi nasıl tutulmalıdır?', 'Sola eğik şekilde', 'Sağa eğik şekilde', 'Hareketsiz ve düz bir doğrultuda sabitleyerek', 'Kafası tamamen serbest bırakılarak', 'C', 'Olası omurilik zedelenmesini tetiklememek adına yaralının başı ve boynu taşınırken hareketsiz, düz bir hizada tutulmalıdır.'),
(17, 4, 2, 'Hatalı sollama yapan bir araca inatlaşarak yol vermeyen ve kazaya sebep olan sürücünün davranışı neyi ihlal eder?', 'Geçiş önceliği kurallarını', 'Trafik adabı, saygıyı ve sabrı', 'Takip mesafesi kuralını', 'Hız limitlerini', 'B', 'Hatalı davranan diğer sürücülerle inatlaşmak ve kaza riskini tetiklemek trafik adabına, saygı ve sabır ilkelerine tamamen aykırıdır.'),
(18, 4, 2, 'Trafik kazası sonrası olay yerinde başka araçların kazaya karışmasını önlemek için ne yapılmalıdır?', 'Aracın dörtlü flaşörleri yakılmalı ve yol kenarına uygun reflektör yerleştirilmelidir', 'Araç hemen terk edilmelidir', 'Korna basılarak beklenmelidir', 'Yoldan geçen diğer araçlardan yardım istenmeden beklenecektir', 'A', 'İkinci bir kazanın önlenmesi için emniyet tedbirleri kapsamında reflektör veya yansıtıcı yerleştirilmesi mecburidir.'),
(19, 4, 3, 'Aracın motor yağı zamanında değiştirilmezse motorun hangi parçaları zarar görebilir?', 'Tüm hareketli ve sürtünen metal parçaları', 'Sadece radyatör', 'Lastikler ve jantlar', 'Egzoz susturucusu', 'A', 'Yağ eskidikçe yağlama özelliğini kaybeder. Sürtünme artacağı için motorun hareketli metal parçaları aşırı aşınır ve yatak sarabilir.'),
(20, 4, 4, 'Sürücülerin trafikte birbirlerine güleryüz göstermesi, selamlaşması ve hoşgörülü yaklaşması trafikte hangisini azaltır?', 'Trafikteki stresi ve gerilimi', 'Yol güvenliğini', 'Hız limitlerini', 'Araç yakıt tüketimini', 'A', 'Olumlu iletişim ve güleryüz, trafikteki agresyonu ve stresi azaltan en etkili trafik adabı unsurudur.'),
(21, 5, 1, 'Kalp durmasına bağlı olarak solunumu da duran bir hastada, ilk masaj basısı göğüs kemiğinin neresine uygulanmalıdır?', 'Göğüs kemiğinin tam ortasına', 'Karın boşluğuna', 'Köprücük kemiğinin hemen üstüne', 'Koltuk altı hizasına', 'A', 'Dış kalp masajı, yetişkinlerde göğüs kemiğinin tam ortasına (iman tahtası) dik olacak şekilde uygulanır.'),
(22, 5, 2, 'Trafik levhalarında ''YOL VER'' anlamına gelen kırmızı kenarlı boş ters üçgen levha hangi yola yerleştirilir?', 'Tali yoldan ana yola bağlanma noktalarına', 'Sadece otoyollara', 'Kavşak içindeki döner alanlara', 'Yerleşim yeri içindeki çıkmaz sokaklara', 'A', 'Ters üçgen (Yol Ver) levhası, tali yoldan ana yola çıkan sürücülere ana yoldaki araçlara yol vermeleri gerektiğini belirtir.'),
(23, 5, 2, 'Aşağıdakilerden hangisi trafikte yayaların güvenle karşıya geçmesini sağlayan geçit türlerindendir?', 'Okul ve yaya geçitleri, alt ve üst geçitler', 'Platformlar', 'Bisiklet yolları', 'Banketler', 'A', 'Okul geçitleri, yaya çizgileri, alt ve üst geçitler yayaların güvenliği için özel inşa edilmiş alanlardır.'),
(24, 5, 3, 'Motor sıcakken radyatör soğutma suyuna çok soğuk su eklenmesi durumunda aşağıdakilerden hangisi meydana gelebilir?', 'Motor bloğu ve silindir kapağı çatlayabilir', 'Frenler tutmayabilir', 'Lastikler patlayabilir', 'Akü şarj etmeyi kesebilir', 'A', 'Sıcak motor parçalarına aniden buz gibi soğuk su dökmek termal şok yaratarak motor bloğunun çatlamasına sebep olur.'),
(25, 5, 4, 'Trafikte engelli bir sürücünün aracına yardım etmeyip inatla kornaya basan bir sürücü hangi trafik adabını ihlal etmiştir?', 'Bencillik ve saygısızlık', 'Empati ve hoşgörü', 'Nezaket', 'Sabır', 'B', 'Empati ve hoşgörü eksikliği sürücünün dezavantajlı kişileri taciz etmesine ve tahammülsüz olmasına sebep olur.'),
(26, 6, 1, 'Koma pozisyonu verilen bir kazazede ile ilgili hangisi doğrudur?', 'Hasta yan yatış konumunda tutulur', 'Hasta tamamen sırtüstü yatırılır', 'Hastaya yemek yedirilir', 'Hastaya su içirilir', 'A', 'Komadaki hastanın solunum yollarını temiz tutmak ve kusma durumunda boğulmasını önlemek amacıyla yarı yan yatış (koma pozisyonu) verilir.'),
(27, 6, 2, 'Yerleşim yeri içindeki kavşaklarda kaç metre kala şerit değiştirmek yasaktır?', '30 metre', '50 metre', '100 metre', '150 metre', 'A', 'Karayolları kanununa göre kavşak yaklaşımlarında şehir içinde 30 metre, şehir dışında ise 150 metre kala şerit değiştirmek yasaktır.'),
(28, 6, 2, 'Taşıt yolu üzerine çizilen yavaşlama uyarı çizgileri (giderek sıklaşan çizgiler) neyi ifade eder?', 'Hızın düşürülmesi ve dikkatli olunması gerektiğini', 'Hızlanılması gerektiğini', 'Park yasağı olduğunu', 'Yolun tamamen kapalı olduğunu', 'A', 'Tırtıklı ve giderek sıklaşan yatay çizgiler, sürücülere yaklaşan tehlikeli alanlar (kavşak, gişe vb.) için yavaşlama uyarısı yapar.'),
(29, 6, 3, 'Akü (şarj) lambasının seyir halindeyken yanmasının temel sebebi hangisi olabilir?', 'Alternatörün aküyü şarj etmemesi (Kayış kopması vb.)', 'Radyatör hortumlarının sızdırması', 'Lastik havalarının yüksek olması', 'Egzozun tıkanmış olması', 'A', 'Seyir halindeyken akü şarj göstergesi yanarsa, şarj dinamosu (alternatör) elektrik üretmiyordur. Araç hemen durdurulmalıdır.'),
(30, 6, 4, 'Karlı yolda zincirsiz yola çıkıp kayarak yolu kapatan ve diğer sürücülerin saatlerce beklemesine neden olan sürücü hangi hakkı ihlal etmiştir?', 'Diğer sürücülerin kullanım ve seyahat haklarını (Kul hakkını)', 'Kendi hakkını', 'Trafik sigortasını', 'Lastik garanti hakkını', 'A', 'Tedbirsiz davranarak kamuya açık yolları kapatmak ve diğer sürücüleri engellemek kul hakkı ve toplumsal sorumluluk ihlalidir.'),
(31, 7, 1, 'Ağızdan ağza yapay solunum yapacak olan ilk yardımcı, kazazedenin burun kanatlarını neden parmaklarıyla kapatır?', 'Havanın akciğerlerden geri çıkmasını önlemek için', 'Kazazedenin yutkunmasını kolaylaştırmak için', 'Havanın burundan dışarı kaçmasını önlemek için', 'Kazazedenin daha rahat nefes alabilmesi için', 'C', 'Yapay solunum sırasında üflenen havanın burundan kaçmaması ve tamamen akciğerlere dolması için kazazedenin burun delikleri kapatılır.'),
(32, 7, 2, 'Aksine bir işaret yoksa, yerleşim yeri dışındaki bölünmüş karayollarında otomobiller için azami hız sınırı saatte kaç kilometredir?', '90', '100', '110', '120', 'C', 'Bölünmüş yollarda otomobil azami hız limiti saatte 110 kilometredir.'),
(33, 7, 2, 'Trafik kazalarında emniyet kemeri kullanılmasının en önemli faydası aşağıdakilerden hangisidir?', 'Araç içindeki gürültüyü azaltması', 'Kaza anında araçtan dışarı fırlamayı veya ölümcül yaralanmaları önlemesi', 'Aracın daha az yakıt yakmasını sağlaması', 'Lastik ömrünü uzatması', 'B', 'Emniyet kemeri çarpışma anındaki atalet kuvvetini absorbe ederek kazazedelerin araçtan fırlamasını engeller.'),
(34, 7, 3, 'Araçta yakıt tasarrufu sağlamak için aşağıdakilerden hangisi yapılmalıdır?', 'Motor yüksek devirde çalıştırılmalıdır', 'Lastiklerin hava basıncı normal değerinde tutulmalıdır', 'Farlar gereksiz yere açık tutulmalıdır', 'Ani duruş ve kalkışlar yapılmalıdır', 'B', 'Düşük hava basınçlı lastikler sürtünmeyi artırır ve yakıt tüketimini yükseltir. Lastik basınçlarının normal değerde olması yakıt tasarrufu sağlar.'),
(35, 7, 4, 'Trafikte karşılaştığı bir sürücüye, yol vermesi gerektiği halde inatlaşarak yol vermeyen sürücünün bu davranışı hangisine örnektir?', 'Empati kurmaya', 'Nezaket göstermeye', 'Trafik adabına aykırı inatlaşmaya', 'Yardımlaşmaya', 'C', 'İnatlaşarak trafik güvenliğini tehlikeye sokmak trafik adabına aykırı bir davranıştır.'),
(36, 8, 1, 'Yaralanmalarda kanayan bölgeye yapılacak ilk müdahale aşağıdakilerden hangidir?', 'Kanayan bölgenin kalp seviyesinin altında tutulması', 'Kanayan yere temiz bir bezle doğrudan baskı uygulanması', 'Yara üzerine hemen tentürdiyot dökülmesi', 'Kanayan bölgenin hareket ettirilmesi', 'B', 'Kanamayı durdurmanın en etkili ilk yardım yöntemi, kanayan damarın üzerine temiz bir bezle doğrudan baskı uygulamaktır.'),
(37, 8, 2, 'Öndeki aracı güvenli takip mesafesi kuralı neye dayanarak hesaplanır?', 'Aracın boyuna', 'Hava sıcaklığına', 'Aracın hızının yarısı kadar metre cinsinden mesafeye', 'Sürücünün yaşına', 'C', 'Takip mesafesi kuralı aracın saatteki hızının en az yarısı kadar metredir (Örn: 80 km/s hız ile giden araç için 40 metre).'),
(38, 8, 2, 'Uyuşturucu veya uyarıcı madde aldığı tespit edilen sürücülere hangi işlem uygulanır?', 'Sürücü belgesi 5 yıl süreyle geri alınır ve idari para cezası verilir.', 'Sadece hafif bir uyarı cezası verilir.', 'Hız sınırını aşmadığı sürece işlem yapılmaz.', 'Aracına el konulur fakat ehliyeti geri verilmez.', 'A', 'Uyuşturucu madde kullanarak araç sürenlerin ehliyetine 5 yıl el konulur ve ağır idari para cezası uygulanır.'),
(39, 8, 3, 'Aracın radyatörüne su ekleneceği zaman motorun sıcaklık durumu nasıl olmalıdır?', 'Çok sıcak olmalıdır', 'Çok soğuk olmalıdır', 'Ilık (rölantide çalıştırılmış veya soğumuş) olmalıdır', 'Sıcaklık durumu fark etmez', 'C', 'Sıcak motor blok ve kapağının çatlamasını önlemek için radyatöre su motor ılık veya rölantide çalışırken yavaşça eklenmelidir.'),
(40, 8, 4, 'Trafik içinde sürücülerin birbirlerine el ve kol hareketleriyle hakaret etmesi hangi adaba aykırıdır?', 'Nezaket ve saygı', 'Bencillik', 'Tahammül', 'Sorumluluk', 'A', 'Hakaret içerikli hareketler nezaket ve saygı ilkelerini ihlal eder.'),
(41, 9, 1, 'Boyun kırığı şüphesi olan bir yaralıya yapılacak ilk yardım uygulamasında hangisi en önemlidir?', 'Yaralının hemen yürütülmesi', 'Boyun bölgesinin mutlaka boyunlukla sabitlenmesi ve hareketsiz tutulması', 'Sırtüstü yatırılıp bacaklarının dikilmesi', 'Ağzına sıcak içecekler verilmesi', 'B', 'Boyun kırıklarında hatalı hareket omurilik felcine yol açabilir. Bu yüzden boyunlukla sabitleme hayati önem taşır.'),
(42, 9, 2, 'Gidişe ayrılan şeritlerden en soldakini sürekli işgal etmek sürücüye hangi cezanın verilmesini gerektirir?', 'Para cezası ve ceza puanı uygulanır.', 'Aracı trafikten men edilir.', 'Sürücü belgesine süresiz el konulur.', 'Hiçbir cezai işlem uygulanmaz.', 'A', 'En sol şerit sadece geçiş (sollama) amaçlıdır. Sürekli işgal edilmesi trafik akışını engeller, para cezası ve ceza puanı verilir.'),
(43, 9, 2, 'Aşağıdakilerden hangisi çevre kirliliğini önleyici sürücü davranışlarındandır?', 'Gereksiz yere korna çalarak gürültü yapmak', 'Aracı rölantide çok uzun süre çalıştırmak', 'Bakımları zamanında yaptırıp motor yağı sızıntılarını önlemek', 'Eski lastikleri yol kenarına bırakmak', 'C', 'Araç bakımlarını zamanında yaptırmak yakıt tasarrufu sağlar, egzoz gazı ve yağ sızıntılarını azaltarak çevre kirliliğini önler.'),
(44, 9, 3, 'Kışın araç soğutma suyuna donmayı engellemek için ne eklenir?', 'Antifriz', 'Saf alkol', 'Motor yağı', 'Tuzlu su', 'A', 'Antifriz, suyun donma noktasını düşürerek kış aylarında motor bloğunun çatlamasını ve soğutma sisteminin donmasını engeller.'),
(45, 9, 4, 'Trafikte engelli sürücülere ayrılmış park yerine aracını park eden engelsiz bir sürücü, engelli bireyin hangi hakkını gasp etmiş olur?', 'Mülkiyet hakkını', 'Seyahat hakkını', 'Kullanım ve erişim hakkını', 'Eğitim hakkını', 'C', 'Engelli otopark yerleri, engelli vatandaşların hayata katılımını kolaylaştırmak içindir. Burayı işgal etmek kullanım hakkının gaspıdır.'),
(46, 10, 1, 'Kazazedenin soluk yoluna yabancı cisim kaçması durumunda uygulanan ve halk arasında ''karına bası uygulama'' olarak bilinen manevranın adı nedir?', 'Heimlich Manevrası', 'Rentek Manevrası', 'Şok Pozisyonu Manevrası', 'Kalp Masajı Manevrası', 'A', 'Solunum yolları tamamen tıkanan kişilerde Heimlich Manevrası uygulanarak cismin dışarı atılması sağlanır.'),
(47, 10, 2, 'Trafik işaret levhalarında görülen kırmızı üçgen içerisindeki semboller genellikle sürücülere neyi bildirir?', 'Yasaklama ve kısıtlamaları', 'Tehlike ve uyarıları', 'Bilgilendirmeleri', 'Yolun tek yönlü olduğunu', 'B', 'Kırmızı üçgen levhalar tehlike uyarı işaretleridir ve sürücüyü ilerideki risklere karşı uyarır.'),
(48, 10, 2, 'Gece arkasındaki aracın far ışıklarından gözü kamaşan bir sürücü ne yapmalıdır?', 'Hızını artırıp kaçmalıdır', 'Aynanın açısını değiştirmeli veya dikiz aynasını gece moduna almalıdır', 'Aniden fren yapıp arkadakini korkutmalıdır', 'Dörlü flaşörleri yakıp durmalıdır', 'B', 'Arkadaki aracın uzun farları gözü alıyorsa dikiz aynası gece konumuna getirilmeli veya açısı değiştirilerek yansıma azaltılmalıdır.'),
(49, 10, 3, 'Dizel motorlarda yakıtın silindir içinde ateşlenmesi nasıl gerçekleşir?', 'Buji kıvılcımı ile', 'Sıkıştırılan sıcak havanın üzerine enjektörle yakıt püskürtülerek', 'Aküden gelen yüksek akım ile', 'Karbüratör yardımıyla', 'B', 'Dizel motorlarda buji yoktur; silindir içindeki yüksek basınçlı sıcak havaya yakıt püskürtülerek kendiliğinden tutuşma sağlanır.'),
(50, 10, 4, 'Trafikte kendi şeridinde yavaş giden sürücünün arkasından sürekli selektör yapıp korna çalarak onu taciz etmek hangi davranışa girer?', 'Trafik güvenliğini artırmaya', 'Sabırsızlık ve nezaketsizliğe', 'Geçiş hakkını korumaya', 'Sürücülerin yardımlaşmasına', 'B', 'Kurallara uygun ilerleyen bir sürücüyü arkadan rahatsız etmek sabırsızlık ve adaba aykırı bir tutumdur.'),
(51, 11, 1, 'Burun kanaması olan bir kazazedeye ilk yardım olarak hangi pozisyon verilmelidir?', 'Baş geriye doğru itilerek sırtüstü yatırılmalı', 'Başı hafifçe öne eğilerek oturtulmalı ve burun kanatları 5 dakika sıkılmalı', 'Yüzüstü yatırılmalı', 'Ayakları yukarı kaldırılmalı', 'B', 'Burun kanamasında başı arkaya atmak kanın yutulmasına sebep olur. Doğrusu başı öne eğip burun kanatlarını sıkmaktır.'),
(52, 11, 2, 'Aşağıdakilerden hangisi çevre kirliliğini artırıcı faktörlerdendir?', 'Araç bakımlarının zamanında yaptırılması', 'Toplu taşıma araçlarının tercih edilmesi', 'Gereksiz yere trafiğe özel araçlarla çıkılması ve rölantide beklenmesi', 'Elektrikli araç kullanımı', 'C', 'Gereksiz yere hususi araba kullanımı ve rölantide çalışma hava kirliliğini doğrudan artıran olumsuz bir alışkanlıktır.'),
(53, 11, 2, 'Alkollü içki almış bir sürücünün güvenli sürüş yeteneğinin kaybolmasında en büyük etken hangisidir?', 'Görme yeteneğinin keskinleşmesi', 'Karar verme ve refleks sürelerinin uzaması/zayıflaması', 'Kas gücünün artması', 'Dikkat dağınıklığının önlenmesi', 'B', 'Alkol merkezi sinir sistemini uyuşturarak refleksleri yavaşlatır ve reaksiyon süresini uzatır.'),
(54, 11, 3, 'Gösterge panelinde yanan ünlem işaretli kırmızı fren hidroliği veya el freni lambası neyi ifade eder?', 'Lastik havasının indiğini', 'Motor yağının tükendiğini', 'El freninin çekili olduğunu veya fren hidrolik seviyesinin düştüğünü', 'Yakıtın bittiğini', 'C', 'Ünlem işaretli kırmızı dairesel lamba el freninin çekili olduğunu ya da fren sisteminde (hidrolik kaçağı vb.) bir arıza olduğunu gösterir.'),
(55, 11, 4, 'Yağmurlu bir günde kaldırımdaki yayaların yanından geçerken hız sınırını düşürerek su sıçratmamaya özen gösteren sürücü, hangi trafik adabı değerine sahiptir?', 'Sabırsızlık', 'Nezaket ve Empati', 'Bencillik', 'Öfke', 'B', 'Yayaları korumak ve rahatsız etmemek nezaket ve empatiye örnektir.'),
(56, 12, 1, 'Açık kırıklarda ilk yardım olarak yapılması gereken en önemli işlem hangisidir?', 'Kırılan kemik uçlarının hemen yerine sokulmaya çalışılması', 'Kırık bölgesinin hareket ettirilmeden temiz bir bezle örtülmesi ve atelle sabitlenmesi', 'Kırık yere sıcak uygulama yapılması', 'Kazazedenin hemen ayağa kaldırılması', 'B', 'Açık kırıklarda kemik uçları dışarıdadır. Enfeksiyonu ve doku harabiyetini önlemek için kemiğe dokunulmaz, üzeri örtülüp atellenir.'),
(57, 12, 2, 'Karayollarında seyreden araçların yüklenmesinde aşağıdakilerden hangisi yasaktır?', 'Yüklerin sıkıca bağlanması', 'Karayolu yapısına ve trafik güvenliğine zarar verecek şekilde yük taşınması', 'Yükün boyunun araç sınırları içinde kalması', 'Tehlikeli maddelerin kurallara uygun taşınması', 'B', 'Trafik güvenliğini tehlikeye sokacak, yola dökülecek veya karayolu köprülerine zarar verecek şekilde yükleme yapmak yasaktır.'),
(58, 12, 2, 'Trafikte geçiş üstünlüğü hakkına sahip ambulansın geldiğini duyan sürücü ne yapmalıdır?', 'Hızlanıp ambulansın önünü açmalıdır', 'Fermuar sistemiyle (sağa ve sola açılarak) koridor oluşturup geçişi kolaylaştırmalıdır', 'Hemen frene basıp durmalıdır', 'Korna çalıp ambulansı durdurmalıdır', 'B', 'Ambulans geldiğinde emniyetli şerit kenarlarına açılarak fermuar yöntemiyle ortada ambulansın geçebileceği şerit açılmalıdır.'),
(59, 12, 3, 'Aracın el freni çekili haldeyken hareket ettirilmeye çalışılması hangisine zarar verir?', 'Fren balatalarının aşınmasına ve ısınmasına', 'Motor yağı pompasına', 'Direksiyon miline', 'Radyatör fanına', 'A', 'El freni çekili gitmek arka tekerleklerin sürekli sıkılmasına, dolayısıyla balata ve disklerin aşırı ısınmasına ve aşınmasına yol açar.'),
(60, 12, 4, 'Kırmızı ışık yandığı sırada geçmekte olan yaya hızlansın diye gaz pedalına basıp motoru bağırtan sürücü hangisini yapmıştır?', 'Yaya hakkına saygısızlık ve sabırsızlık', 'Hoşgörü', 'Öfke kontrolü', 'Yardımseverlik', 'A', 'Yol hakkı yayada olmasına rağmen onu taciz etmek ve hızlanmaya zorlamak yaya hakkına saygısızlık ve sabırsızlıktır.'),
(61, 13, 1, 'Aşağıdakilerden hangisi ilk yardımın ABC''si içinde yer alan ''C'' harfinin karşılığıdır?', 'Havayolu açıklığının değerlendirilmesi', 'Solunumunun değerlendirilmesi (Bak-Dinle-Hisset)', 'Dolaşımın değerlendirilmesi (Nabız kontrolü)', 'Bilinç kontrolü', 'C', 'İlk yardımın ABC''si: A (Airway-Havayolu), B (Breathing-Solunum), C (Circulation-Dolaşım) demektir.'),
(62, 13, 2, 'Geçiş üstünlüğü hakkı hangi durumda kullanılamaz?', 'Görev hali dışında ve diğer kişilerin can ve mal güvenliğini tehlikeye sokacak durumlarda', 'Sadece hava yağmurlu olduğunda', 'Gece saatlerinde', 'Hafta sonu tatillerinde', 'A', 'Geçiş üstünlüğü sadece görev halinde ve can/mal güvenliğini tehlikeye atmamak şartıyla kullanılabilir.'),
(63, 13, 2, 'Park edilen araç yokuş aşağı yönlü duruyorsa tekerlekler ne tarafa çevrilir?', 'Kaldırım tarafına (Sağa)', 'Yol ortasına (Sola)', 'Düz tutulur', 'Fark etmez', 'A', 'Yokuş aşağı parklarda kayma durumunda aracın kaldırıma çarpıp durması için direksiyon kaldırıma doğru (sağa) çevrilir.'),
(64, 13, 3, 'Soğutma sistemindeki radyatörün görevi aşağıdakilerden hangisidir?', 'Motora yakıt pompalamak', 'Motor yağını temizlemek', 'Soğutma suyuna depoluk etmek ve suyun soğumasını sağlamak', 'Ateşlemeyi başlatmak', 'C', 'Radyatör içindeki kılcal borular sayesinde motordan gelen sıcak suyun hava ile temas ederek soğumasını sağlar.'),
(65, 13, 4, 'Sürücü belgesi (ehliyet) sınıfı ''B'' olan bir kişi hangi aracı kullanamaz?', 'Otomobil', 'Kamyonet', 'Traktör', 'Motosiklet (A sınıfı gerektiren)', 'D', 'B sınıfı ehliyet otomobil ve kamyonet sürer, ayrıca M ve F (traktör) yetkisi verir. Ancak A sınıfı büyük motorları süremez.'),
(66, 14, 1, 'Temel Yaşam Desteğinde suni solunum yapmadan önce bebeklerde soluk yolu tıkanıklığını gidermek için sırt vuruşu nereye uygulanır?', 'Göğüs kemiğinin üzerine', 'İki kürek kemiğinin tam ortasına baş aşağı pozisyonda', 'Karın bölgesine', 'Alın bölgesine', 'B', 'Bebeklerde tıkanıklık durumunda bebek kol üzerine yüzüstü yatırılır, iki kürek kemiğinin ortasına hafifçe sırt vuruşu uygulanır.'),
(67, 14, 2, 'Aşağıdaki trafik işaretlerinden hangisi ''Girişi Olmayan Yol'' anlamındadır?', 'Kırmızı daire içinde beyaz yatay çizgi sembolü', 'Kırmızı üçgen içinde ünlem işareti', 'Mavi kare içinde beyaz ok sembolü', 'Yuvarlak içinde bisiklet resmi', 'A', 'Beyaz yatay çizgili kırmızı yuvarlak levha ''Girişi Olmayan Yol'' (Tek yönlü sokakların çıkışı) anlamındadır.'),
(68, 14, 2, 'Gece sürüşünde karşı yönden gelen araç sürücüsünün gözünü kamaştırmamak için hangi farlar kullanılmalıdır?', 'Uzağı gösteren farlar (Uzunlar)', 'Yakını gösteren farlar (Kısalar)', 'Sis farları', 'Sadece park lambaları', 'B', 'Karşıdaki sürücünün görüşünü engellememek ve güvenliği bozmamak için gece karşılaşmalarında kısa farlar yakılmalıdır.'),
(69, 14, 3, 'Akü üzerinde bulunan artı (+) ve eksi (-) kutup başları ile ilgili olarak hangisi doğrudur?', 'Artı kutup başı daha ince olur', 'Artı kutup başı eksi kutup başına göre daha kalın olur', 'Kutup başları aynı kalınlıktadır', 'Eksi kutup başı mavi renktedir', 'B', 'Akü kutuplarının karıştırılmaması için artı (+) kutup başı yapısal olarak eksi (-) kutup başına göre daha kalın imal edilir.'),
(70, 14, 4, 'Sürücünün trafikte hatalı bir sollamadan dolayı tehlikeye sebep olduktan sonra diğer sürücüden el işaretiyle özür dilemesi neyi gösterir?', 'Korkak olduğunu', 'Hatalı sürüşe devam edeceğini', 'Trafikte saygılı ve hoşgörülü davrandığını', 'Yol hakkını tamamen kaybettiğini', 'C', 'Hatalı durumlarda nezaketle iletişim kurmak ve özür dilemek hoşgörülü trafik adabının göstergesidir.'),
(71, 15, 1, 'Koma pozisyonundaki bir kazazedede aşağıdakilerden hangisi gözlenmez?', 'Bilinç kaybı', 'İdrar kaçırma', 'Yutkunma ve öksürük gibi reflekslerin korunması', 'Uyarıcılara tepkisizlik', 'C', 'Koma derin bir bilinçsizlik halidir. Yutkunma, öksürük ve diğer koruyucu refleksler tamamen kaybolur.'),
(72, 15, 2, 'Kavşaklarda geçiş önceliği kurallarına göre, döner kavşağa giren araç ile döner kavşak dışındaki araç karşılaştığında geçiş hakkı hangisine aittir?', 'Döner kavşak dışındaki araca', 'Döner kavşak içindeki araca', 'Hızlı giden araca', 'Büyük olan araca', 'B', 'Kavşak kurallarına göre döner kavşak içindeki aracın geçiş önceliği vardır. Dışarıdaki araç beklemelidir.'),
(73, 15, 2, 'Karayollarında gece seyir halindeyken uzağı gösteren farlar (uzunlar) yakıldığında gösterge panelinde hangi renk lamba yanar?', 'Mavi', 'Yeşil', 'Kırmızı', 'Sarı', 'A', 'Gösterge panelinde uzun far simgesi yandığında ışık rengi mavi olur. Kısa farlarda ise yeşil lamba yanar.'),
(74, 15, 3, 'Aracın lastik havalarının normalden az (düşük) olması hangisine yol açar?', 'Lastiklerin kenar kısımlarından aşınmasına ve yakıt tüketiminin artmasına', 'Lastiklerin ortadan aşınmasına', 'Aracın daha hızlı gitmesine', 'Fren mesafesinin kısalmasına', 'A', 'Düşük hava basınçlı lastiklerin kenarları yere basar ve buralardan aşınır, yuvarlanma direnci arttığı için yakıt sarfiyatı artar.'),
(75, 15, 4, 'Ambulans veya itfaiyeye yol vermeyip arkasından gelen emniyet şeridini kullanarak trafikten kaçmaya çalışan sürücü hangi adaba uymaz?', 'Sabırsızlık', 'Hak gaspı ve sorumluluk bilinci eksikliği', 'Bencillik', 'Korkaklık', 'B', 'Emniyet şeritlerini ihlal etmek hak gaspına girer ve sorumluluk bilincine aykırı davranıştır.'),
(76, 16, 1, 'Kazazedenin bilinci kapalı, solunumu var ancak kusma riski yüksekse hangi pozisyonda bekletilmelidir?', 'Koma Pozisyonu (Yan yatış)', 'Sırtüstü yatış', 'Yarı oturuş', 'Ters asılma', 'A', 'Kusmuğun soluk borusuna kaçmasını önlemek için bilinci kapalı soluk alan kazazede Koma (yan yatış) pozisyonuna alınır.'),
(77, 16, 2, 'Uzağı gösteren ışıklar (uzun farlar) kaç metreyi aydınlatmalıdır?', '100 metre', '150 metre', '200 metre', '250 metre', 'A', 'Karayolları mevzuatına göre aracın uzun farları en az 100 metreyi, kısa farları ise en az 25 metreyi aydınlatmak zorundadır.'),
(78, 16, 2, 'Sürücülerin şerit değiştirmeden önce vermesi gereken sinyal ne zaman kapatılmalıdır?', 'Şerit değiştirme işlemi tamamlandığı anda', 'Şeride girmeye başlamadan hemen önce', 'Sola/sağa dönüşten 5 dakika sonra', 'Hiç kapatılmaz', 'A', 'Sinyal şerit değiştirme veya dönüş manevrası tamamen bittikten hemen sonra kapatılmalıdır.'),
(79, 16, 3, 'Hararet yapmış bir motorda radyatör kapağı nasıl açılmalıdır?', 'Hızlıca çevrilerek hemen çıkarılmalıdır', 'Motor tamamen durdurulduktan ve soğuduktan sonra kalın bir bezle basıncı yavaşça düşürülerek açılmalıdır', 'Motor çalışırken soğuk su dökülüp hemen açılmalıdır', 'Kapak açılmaz, radyatör kırılmalıdır', 'B', 'Sıcak su fışkırmasını önlemek için motor soğumalı, kapak kalın bir bezle hafifçe gevşetilerek buhar basıncı alınmalı ve ardından açılmalıdır.'),
(80, 16, 4, 'Kafa kırığı şüphesi olan bir kazazedede burun ve kulaktan kan gelmesi ile birlikte geçici bilinç kaybı olması neyin belirtisidir?', 'Kafatası kırığı ve beyin hasarının', 'Akciğer yırtılmasının', 'Mide kanamasının', 'Böbrek rahatsızlığının', 'A', 'Burun ve kulaktan beyin omurilik sıvısı karışık kan gelmesi kafatası tabanı kırıklarında beyin hasarı belirtisidir.'),
(81, 17, 1, 'Çocuklarda temel yaşam desteği uygulanırken göğüs kemiği kaç cm aşağı inecek şekilde basınç uygulanır?', '2', '5', '8', '10', 'B', 'Çocuklarda göğüs basısı derinliği 5 cm (yandan bakıldığında göğüs yüksekliğinin 1/3''ü) olacak şekilde uygulanır.'),
(82, 17, 2, 'Trafik kazası gördüğünde durup ilk yardım uygulamayan veya yetkililere bildirmeyen sürücüye ne ceza verilir?', 'Sadece sözlü uyarı', 'Para ve ceza puanı', 'Ehliyete süresiz el koyma', 'Trafikten men', 'B', 'Kazayı yetkililere bildirmemek ve ilk yardım yapmamak idari para cezası ve ceza puanı gerektirir.'),
(83, 17, 2, 'Geçiş kolaylığı sağlamak için sürücüler dar yollarda kimlere yol vermelidir?', 'Ağır araçlar hafif araçlara', 'Hızlı giden araçlar yavaş gidenlere', 'Otomobiller kamyonlara', 'Motosikletler traktörlere', 'A', 'Kural gereği daralan taşıt yollarında hantal ve ağır araçlar daha kıvrak olan hafif araçlara geçiş önceliği verir.'),
(84, 17, 3, 'Lastiklerin üzerindeki rakamlar ve harfler (örn: 195/65 R15) neyi gösterir?', 'Lastik ömrünü', 'Lastik ebatlarını ve jant çapını', 'Lastik markasını', 'Lastik basınç limitini', 'B', 'Lastik üzerindeki bu değerler taban genişliği, yanak yüksekliği oranı ve jant çapı gibi ebatları gösterir.'),
(85, 17, 4, 'Trafikte engelli bir yayanın karşıdan karşıya geçmesine yardımcı olan sürücü hangi adaba sahiptir?', 'Bencillik', 'Sabırsızlık', 'Diğergamlık ve yardımlaşma', 'İnatlaşma', 'C', 'Dezavantajlı gruplara yardımcı olmak diğergamlık ve yardımlaşma bilincinin ürünüdür.'),
(86, 18, 1, 'Kazazedenin ağzında yabancı cisim veya takma diş varsa ilk yapay solunum öncesi ne yapılmalıdır?', 'Cisimler parmakla temizlenerek çıkarılmalıdır', 'Doğrudan üflenmelidir', 'Su içirilmelidir', 'Kafası sağa sola sallanmalıdır', 'A', 'Solunum yollarının tamamen açık olduğundan emin olmak için ağız içi kontrol edilir ve yabancı cisimler çıkarılır.'),
(87, 18, 2, 'Otoyollarda sürücülerin asgari (en az) hız sınırı saatte kaç kilometredir?', '30', '40', '50', '60', 'B', 'Otoyola giren araçların hızı saatte 40 kilometrenin altına düşmemelidir.'),
(88, 18, 2, 'Aşağıdakilerden hangisi sürücünün uykusuz ve yorgun yola çıkmasının bir sonucudur?', 'Dikkat seviyesinin artması', 'Refleks sürelerinin uzaması ve kaza riskinin artması', 'Yakıt tasarrufu sağlanması', 'Lastik aşınmasının azalması', 'B', 'Yorgunluk ve uykusuzluk tepki verme süresini uzatır, direksiyon kontrolünü zorlaştırır.'),
(89, 18, 3, 'Aracın fren mesafesini etkileyen en önemli dış faktör aşağıdakilerden hangisidir?', 'Yolun eğimi ve yol yüzeyinin kayganlığı (ıslak/karlı)', 'Yakıt deposunun doluluğu', 'Farların açık olması', 'Müzik sesinin seviyesi', 'A', 'Yolun kayganlığı (yağmurlu/karlı) lastiklerin tutunmasını azaltarak durma mesafesini doğrudan artırır.'),
(90, 18, 4, 'Trafikte ambulansın peşine takılarak onun açtığı koridoru kendi şeridi gibi kullanan sürücünün davranışı neyi ihlal eder?', 'Hız sınırlarını', 'Kul hakkını ve adabı', 'Takip mesafesini', 'Lastik ömrünü', 'B', 'Acil durum araçlarının açtığı yoldan faydalanıp diğer bekleyenlerin önüne geçmek kul hakkını ve trafik adabını ihlal eder.');
